// 4 filters: pipeline whitelist + status whitelist + Bot_n8n_OFF check + NOT /start command
const raw = $input.first().json;
// AmoCRM returns lead wrapped in "data" string — unwrap
const lead = raw.data ? JSON.parse(raw.data) : raw;
const constants = $('Constants').first().json;
const webhookBody = $('Webhook').first().json.body;

const pipelineId = lead.pipeline_id;
const statusId = lead.status_id;

const botOff = (lead.custom_fields_values || []).find(
  f => f.field_id === constants.BOT_OFF_FIELD_ID
)?.values?.[0]?.value === true;

const pipelineOK = (constants.ALLOWED_PIPELINES || []).includes(pipelineId);
const statusOK = (constants.ALLOWED_STATUSES_NEW || []).includes(statusId);
const botOK = !botOff;

// Phase 3.9.7: ignore /start — это команда Telegram, не контент
const text = (webhookBody['message[add][0][text]'] || '').trim();
const isStartCommand = text === '/start' || text.startsWith('/start ') || text.startsWith('/start@');
const notStartOK = !isStartCommand;

const allow = pipelineOK && statusOK && botOK && notStartOK;

return [{
  json: {
    allow,
    lead,
    constants,
    webhook_body: webhookBody,
    pipeline_id: pipelineId,
    status_id: statusId,
    bot_off: botOff,
    is_start_command: isStartCommand,
    reason: allow ? 'ok' : `pipelineOK=${pipelineOK} statusOK=${statusOK} botOK=${botOK} notStartOK=${notStartOK}`
  }
}];

// Build Context v3.2: абсолютная память из Supabase + state + prompt_for_agent (Колобок паттерн: префиксы ТОЛЬКО при наличии контекста)
const chatHistoryItems = $('Load Chat History').all();
const sessionItems = $('Load Session').all();
const rawLead = $('GET lead').first().json;
const lead = rawLead.data ? JSON.parse(rawLead.data) : rawLead;
const constants = $('Constants').first().json;
const pipeline_id = lead.pipeline_id;
const pipeline_country = (constants.COUNTRY_BY_PIPELINE || {})[String(pipeline_id)] || 'UNKNOWN';
const body = $('Webhook').first().json.body;

const leadId = body['message[add][0][element_id]'] || body['message[add][0][entity_id]'] || '';
const chatId = body['message[add][0][chat_id]'] || '';
const talkId = body['message[add][0][talk_id]'] || '';
const contactId = body['message[add][0][contact_id]'] || '';
const contactName = body['message[add][0][author][name]'] || 'Candidate';
const accountUrl = body['account[_links][self]'] || '';
const accountId = body['account[id]'] || '';
const text = body['message[add][0][text]'] || '';
const origin = body['message[add][0][origin]'] || '';

// Attachments
const attachments = [];
const attUrl0 = body['message[add][0][attachments][0][url]'] || body['message[add][0][attachment][link]'];
const attType0 = body['message[add][0][attachments][0][type]'] || body['message[add][0][attachment][type]'];
if (attUrl0) attachments.push({ url: attUrl0, type: attType0 || '' });
for (let i = 1; i < 10; i++) {
  const url = body[`message[add][0][attachments][${i}][url]`];
  const type = body[`message[add][0][attachments][${i}][type]`];
  if (!url) break;
  attachments.push({ url, type });
}

// HISTORY из Supabase chat_logs
const history = chatHistoryItems
  .filter(item => item.json && item.json.id)
  .map(item => ({
    role: item.json.role,
    content: item.json.content || '',
    language: item.json.language || null,
    timestamp: item.json.created_at
  }))
  .sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp));

// STATE из chat_sessions
const sessionRow = sessionItems.length > 0 && sessionItems[0].json && sessionItems[0].json.lead_id
  ? sessionItems[0].json : null;

const state = sessionRow ? {
  language: sessionRow.language || null,
  scenario: sessionRow.scenario || null,
  in_kazakhstan: sessionRow.in_kazakhstan,
  last_step: sessionRow.last_step || 'start',
  current_country: sessionRow.current_country || null,
  current_city: sessionRow.current_city || null,
  interested_vacancy: sessionRow.interested_vacancy || null,
  first_name: sessionRow.first_name || null,
  internal_full_name: sessionRow.internal_full_name || null,
  client_folder_link: sessionRow.client_folder_link || null,
  documents_received: sessionRow.documents_received || [],
  transition_to_qualified: sessionRow.transition_to_qualified || false,
  english_level_observed: sessionRow.english_level_observed || null
} : {
  language: null, scenario: null, in_kazakhstan: null, last_step: 'start',
  current_country: null, current_city: null, interested_vacancy: null,
  first_name: null, internal_full_name: null, client_folder_link: null,
  documents_received: [], transition_to_qualified: false, english_level_observed: null
};

state.documents_pending = ['cv', 'video', 'recommendations', 'police_clearance', 'medical_book']
  .filter(d => !state.documents_received.includes(d));

// ПРОМПТ ДЛЯ АГЕНТА — КОЛОБОК ПАТТЕРН:
// Префиксы [PREVIOUS]/[STATE]/[NEW MESSAGE]/[ATTACHMENTS] ДОБАВЛЯЮТСЯ ТОЛЬКО при наличии контекста.
// Если это первое сообщение (пустая история, нет session, нет attachments) — отдаём ГОЛЫЙ current_message.
// Это предотвращает игнорирование systemMessage и examples блоков.
const hasContext = history.length > 0 || sessionRow !== null;
const hasAttachments = attachments.length > 0;

let prompt_for_agent;
if (!hasContext && !hasAttachments) {
  // Первое сообщение — голый текст (как в exec 7889 правильно работало)
  prompt_for_agent = text || '[no text — attachment only]';
} else {
  // Есть контекст — формируем структуру
  const promptParts = [];

  if (history.length > 0) {
    const historyText = history.map(h => {
      const role = h.role === 'user' ? 'Candidate' : 'Bot';
      return `${role}: ${h.content}`;
    }).join('\n');
    promptParts.push(`[PREVIOUS CONVERSATION — ${history.length} messages, use for context, do NOT repeat questions already asked]\n${historyText}`);
  }

  if (sessionRow) {
    const stateLines = [];
    if (state.language) stateLines.push(`Language: ${state.language}`);
    if (state.scenario) stateLines.push(`Scenario: ${state.scenario}`);
    if (state.in_kazakhstan !== null) stateLines.push(`In Kazakhstan: ${state.in_kazakhstan}`);
    if (state.last_step) stateLines.push(`Last completed step: ${state.last_step}`);
    if (state.current_country) stateLines.push(`Current country: ${state.current_country}`);
    if (state.current_city) stateLines.push(`Current city: ${state.current_city}`);
    if (state.interested_vacancy) stateLines.push(`Interested vacancy: ${state.interested_vacancy}`);
    if (state.first_name) stateLines.push(`Candidate first name: ${state.first_name}`);
    if (state.documents_received.length) stateLines.push(`Documents received: ${state.documents_received.join(', ')}`);
    if (stateLines.length) promptParts.push(`[STATE — результаты предыдущих выяснений]\n${stateLines.join('\n')}`);
  }

  promptParts.push(`[NEW MESSAGE FROM CANDIDATE]\n${text || '[no text — attachment only]'}`);

  if (hasAttachments) {
    promptParts.push(`[ATTACHMENTS]\n${attachments.map(a => `- ${a.type}: ${a.url}`).join('\n')}`);
  }

  prompt_for_agent = promptParts.join('\n\n');
}

return [{
  json: {
    lead_id: leadId,
    pipeline_id,
    pipeline_country,
    chat_id: chatId,
    talk_id: talkId,
    contact_id: contactId,
    contact_name: contactName,
    account_url: accountUrl,
    account_id: accountId,
    current_message: text,
    attachments,
    has_voice: attachments.some(a => /audio|voice/.test(a.type || '')),
    has_video: attachments.some(a => (a.type || '').startsWith('video')),
    has_document: attachments.some(a => /pdf|doc|docx|file/i.test(a.type || '')),
      has_image: attachments.some(a => /picture|image|jpe?g|png|webp|gif|tiff/i.test(a.type || '')),
    history,
    state,
    constants,
    prompt_for_agent
  }
}];

// Mapping v3.3: 4 fallback для client_google_link
// Phase 3.9.11 Fix: + 4-й fallback = Drive create folder (video) из video ветки.
// Решает: видео первым → создаётся папка в video пути → её URL должен попасть в PATCH lead + [КЛИЕНТСКАЯ ССЫЛКА].
const raw = $input.first().json;
const aiOutput = raw.output || raw;
const context = $('Build Context').first().json;
const constants = context.constants;

// --- documents_received hardening ---
const priorDocs = Array.isArray($('Refresh Context').first().json.state?.documents_received)
  ? $('Refresh Context').first().json.state.documents_received : [];
const docsSet = new Set(priorDocs);
// hard signals — these branches only run when the doc actually arrived
try { const s = $('Set CV result').all();  if (s.length && s[0].json && s[0].json.cv_client_link)  docsSet.add('cv');    } catch(e){}
try { const s = $('Set Video merge').all(); if (s.length && s[0].json && s[0].json.video_uploaded) docsSet.add('video'); } catch(e){}
// agent-asserted — recommendations / police_clearance / medical_book
const aiDocs = Array.isArray(aiOutput.state_documents_received) ? aiOutput.state_documents_received : [];
aiDocs.forEach(d => { if (d) docsSet.add(String(d)); });
const documents_received_final = [...docsSet];

// 1. Set CV result (PDF путь, только в этой execution)
let cv_link_from_set = null;
try {
  const setCV = $('Set CV result').all();
  if (setCV.length > 0 && setCV[0].json && setCV[0].json.cv_client_link) {
    cv_link_from_set = setCV[0].json.cv_client_link;
  }
} catch (e) {
  cv_link_from_set = null;
}

// 2. AI output
const ai_link = aiOutput.state_client_folder_link || null;

// 3. state из Supabase chat_sessions (персистентно между execution)
const state_link = context.state?.client_folder_link || null;

// 4. Drive create folder (video) — video ветка создала папку сейчас
//    только в этой execution + только когда видео пришло ПЕРВЫМ (без PDF)
let video_folder_link = null;
try {
  const driveCreateVideo = $('Drive create folder (video)').all();
  if (driveCreateVideo.length > 0 && driveCreateVideo[0].json && driveCreateVideo[0].json.id) {
    video_folder_link = `https://drive.google.com/drive/folders/${driveCreateVideo[0].json.id}`;
  }
} catch (e) {
  video_folder_link = null;
}

const client_google_link_final = cv_link_from_set || ai_link || state_link || video_folder_link || null;

return [{
  json: {
    lead_id: context.lead_id,
    account_url: context.account_url,
    current_message: context.current_message || '',
    attachments: context.attachments || [],
    main_note_text: aiOutput.main_note_text || '',
    summary_note_text: aiOutput.summary_note_text || '',
    transition_to_qualified: aiOutput.transition_to_qualified === true,
    qualified_status_id: (constants.QUALIFIED_STATUS_BY_PIPELINE || {})[String($('Build Context').first().json.pipeline_id)] || constants.QUALIFIED_STATUS_ID,
    new_lead_name: aiOutput.state_first_name || null,
    client_google_link: client_google_link_final,
    client_google_link_field_id: constants.CLIENT_GOOGLE_LINK_FIELD_ID,
    chat_id: context.chat_id,
    talk_id: context.talk_id,
    contact_id: context.contact_id,
    account_id: context.account_id,
    account_id_amocrm: constants.ACCOUNT_ID_AMOCRM,
    reply_text: aiOutput.reply_text || 'OK',
    reply_language: aiOutput.reply_language || 'EN',
    english_level_observed: aiOutput.english_level_observed || '',
    state_language: aiOutput.state_language || aiOutput.reply_language || 'EN',
    state_scenario: aiOutput.state_scenario || '',
    state_in_kazakhstan: aiOutput.state_in_kazakhstan,
    state_last_step: aiOutput.state_last_step || 'start',
    state_current_country: aiOutput.state_current_country || '',
    state_current_city: aiOutput.state_current_city || '',
    state_interested_vacancy: aiOutput.state_interested_vacancy || '',
    state_first_name: aiOutput.state_first_name || '',
    state_client_folder_link: client_google_link_final || '', 
    state_documents_received: documents_received_final
  }
}];

// Notes prep v3.2: find existing [MAIN]/[SUMMARY] from Get AmoCRM Notes (распаковка data обёртки AmoCRM)
// Phase 3.9.7 Fix 2: детерминированная подмена [КЛИЕНТСКАЯ ССЫЛКА] в main_note_text на фактический URL,
// если он есть в client_google_link. Не зависит от поведения Sonnet 4.6.
const m = $('Mapping').first().json;

// AmoCRM возвращает JSON в строке data — распаковываем
const raw = $input.first().json;
const parsed = raw.data ? JSON.parse(raw.data) : raw;
const allNotes = parsed._embedded?.notes || [];

const mainNote = allNotes.find(n => (n.params?.text || '').startsWith('[ОСНОВНАЯ ИНФОРМАЦИЯ]'));
const summaryNote = allNotes.find(n => (n.params?.text || '').startsWith('[КРАТКИЕ ВЫВОДЫ ПО КАНДИДАТУ]'));
const mainNoteId = mainNote?.id || null;
const summaryNoteId = summaryNote?.id || null;

// ДЕТЕРМИНИРОВАННАЯ ПОДМЕНА [КЛИЕНТСКАЯ ССЫЛКА] на фактический URL
let mainText = m.main_note_text || '';
if (m.client_google_link && mainText) {
  // Заменить строку после "[КЛИЕНТСКАЯ ССЫЛКА]\n" (любой текст до следующего \n) на наш URL
  mainText = mainText.replace(
    /\[КЛИЕНТСКАЯ ССЫЛКА\]\n[^\n]+/,
    `[КЛИЕНТСКАЯ ССЫЛКА]\n${m.client_google_link}`
  );
}

// Build main note body — with id for PATCH, without for POST
const mainPayload = { note_type: 'common', params: { text: mainText } };
if (mainNoteId) mainPayload.id = mainNoteId;
const mainNoteBody = JSON.stringify([mainPayload]);
const mainNoteMethod = mainNoteId ? 'PATCH' : 'POST';

// Build summary note body
let summaryNoteBody = null;
let summaryNoteMethod = null;
if (m.summary_note_text) {
  const summaryPayload = { note_type: 'common', params: { text: m.summary_note_text } };
  if (summaryNoteId) summaryPayload.id = summaryNoteId;
  summaryNoteBody = JSON.stringify([summaryPayload]);
  summaryNoteMethod = summaryNoteId ? 'PATCH' : 'POST';
}

// Lead patch
const leadPatchObj = {};
if (m.transition_to_qualified) leadPatchObj.status_id = m.qualified_status_id;
if (m.new_lead_name) leadPatchObj.name = m.new_lead_name;
if (m.client_google_link) {
  leadPatchObj.custom_fields_values = [{
    field_id: m.client_google_link_field_id,
    values: [{ value: m.client_google_link }]
  }];
}
const hasLeadPatch = Object.keys(leadPatchObj).length > 0;
const leadPatchBody = hasLeadPatch ? JSON.stringify(leadPatchObj) : null;

return [{
  json: {
    ...m,
    main_note_text_final: mainText,
    main_note_id: mainNoteId,
    summary_note_id: summaryNoteId,
    main_note_body: mainNoteBody,
    main_note_method: mainNoteMethod,
    summary_note_body: summaryNoteBody,
    summary_note_method: summaryNoteMethod,
    has_summary: !!m.summary_note_text,
    summary_existed: !!summaryNoteId,
    lead_patch_body: leadPatchBody,
    has_lead_patch: hasLeadPatch
  }
}];

