// Phase 3.9.11c: безопасный resolve folder_id после Merge CV paths
// Приоритет:
//   1. Drive create folder (FALSE branch search no found → create)
//   2. Drive search folder (CV) (FALSE branch IF folder → search found in Drive)
//   3. state.client_folder_link (TRUE branch IF folder — papka уже была)
const context = $('Build Context').first().json;
let folder_id = null;
let folder_url = null;

// 1. Drive create folder — свежая созданная
try {
  const driveCreate = $('Drive create folder').all();
  if (driveCreate.length > 0 && driveCreate[0].json && driveCreate[0].json.id) {
    folder_id = driveCreate[0].json.id;
    folder_url = `https://drive.google.com/drive/folders/${folder_id}`;
  }
} catch (e) {}

// 2. Drive search — нашли папку созданную другим execution (race protection)
if (!folder_id) {
  try {
    const driveSearch = $('Drive search folder (CV)').all();
    if (driveSearch.length > 0 && driveSearch[0].json && driveSearch[0].json.id) {
      folder_id = driveSearch[0].json.id;
      folder_url = `https://drive.google.com/drive/folders/${folder_id}`;
    }
  } catch (e) {}
}

// 3. state.client_folder_link (TRUE branch IF folder — был видео раньше)
if (!folder_id) {
  folder_url = context.state?.client_folder_link || '';
  folder_id = folder_url ? (folder_url.split('/folders/')[1] || 'root') : 'root';
}

return [{
  json: {
    ...($input.first()?.json || {}),
    folder_id,
    folder_url
  }
}];

// Phase 3.9.11c: безопасный resolve folder_id для video
// Приоритет:
//   1. Drive create folder (video) — свежая созданная
//   2. Drive search folder (video) — нашли папку созданную другим execution (race protection)
//   3. state.client_folder_link — был PDF раньше
const context = $('Build Context').first().json;
let folder_id = null;
let folder_url = null;

try {
  const driveCreate = $('Drive create folder (video)').all();
  if (driveCreate.length > 0 && driveCreate[0].json && driveCreate[0].json.id) {
    folder_id = driveCreate[0].json.id;
    folder_url = `https://drive.google.com/drive/folders/${folder_id}`;
  }
} catch (e) {}

if (!folder_id) {
  try {
    const driveSearch = $('Drive search folder (video)').all();
    if (driveSearch.length > 0 && driveSearch[0].json && driveSearch[0].json.id) {
      folder_id = driveSearch[0].json.id;
      folder_url = `https://drive.google.com/drive/folders/${folder_id}`;
    }
  } catch (e) {}
}

if (!folder_id) {
  folder_url = context.state?.client_folder_link || '';
  folder_id = folder_url ? (folder_url.split('/folders/')[1] || 'root') : 'root';
}

// Сохраняем binary из Download video file
const input = $input.first();
return [{
  json: {
    ...(input?.json || {}),
    folder_id,
    folder_url
  },
  binary: input?.binary
}];

// Phase 3.9.11c: rebuild prompt_for_agent с свежим state из Load Session reload
const buildContext = $('Build Context').first().json;
const pc = buildContext.pipeline_country;
const injectPipeline = (pc === 'RU' || pc === 'KZ');
const pipelineBlock = pc === 'RU'
  ? `[PIPELINE] Russia — candidate wrote to the RU line. Apply ru_en_relocate or ru_local per the candidate's language.`
  : `[PIPELINE] Kazakhstan — candidate wrote to the KZ line.`;
const reloadItems = $('Load Session reload').all();
const reload = reloadItems.length > 0 ? reloadItems[0].json : null;

const freshState = reload ? {
  language: reload.language,
  scenario: reload.scenario,
  in_kazakhstan: reload.in_kazakhstan,
  last_step: reload.last_step || 'start',
  current_country: reload.current_country,
  current_city: reload.current_city,
  interested_vacancy: reload.interested_vacancy,
  first_name: reload.first_name,
  internal_full_name: reload.internal_full_name,
  client_folder_link: reload.client_folder_link,
  documents_received: reload.documents_received || [],
  transition_to_qualified: reload.transition_to_qualified || false,
  english_level_observed: reload.english_level_observed
} : (buildContext.state || {});

freshState.documents_pending = ['cv', 'video', 'recommendations', 'police_clearance', 'medical_book']
  .filter(d => !(freshState.documents_received || []).includes(d));

const history = buildContext.history || [];
let text = buildContext.current_message || '';
try { const n = $('Set CV result').all();   if (n[0]?.json?.current_message) text = n[0].json.current_message; } catch(e){}
try { const n = $('Set Voice merge').all(); if (n[0]?.json?.current_message) text = n[0].json.current_message; } catch(e){}
try { const n = $('Set Video merge').all(); if (n[0]?.json?.current_message) text = n[0].json.current_message; } catch(e){}
const attachments = buildContext.attachments || [];

const hasContext = history.length > 0 || reload !== null;
const hasAttachments = attachments.length > 0;

let prompt_for_agent;
if (!hasContext && !hasAttachments) {
  prompt_for_agent = injectPipeline
    ? `${pipelineBlock}\n\n${text || '[no text — attachment only]'}`
    : (text || '[no text — attachment only]');
} else {
  const promptParts = [];
  if (injectPipeline) promptParts.push(pipelineBlock);
  if (history.length > 0) {
    const historyText = history.map(h => {
      const role = h.role === 'user' ? 'Candidate' : 'Bot';
      return `${role}: ${h.content}`;
    }).join('\n');
    promptParts.push(`[PREVIOUS CONVERSATION — ${history.length} messages, use for context, do NOT repeat questions already asked]\n${historyText}`);
  }
  if (reload !== null) {
    const stateLines = [];
    if (freshState.language) stateLines.push(`Language: ${freshState.language}`);
    if (freshState.scenario) stateLines.push(`Scenario: ${freshState.scenario}`);
    if (freshState.in_kazakhstan !== null && freshState.in_kazakhstan !== undefined) stateLines.push(`In Kazakhstan: ${freshState.in_kazakhstan}`);
    if (freshState.last_step) stateLines.push(`Last completed step: ${freshState.last_step}`);
    if (freshState.current_country) stateLines.push(`Current country: ${freshState.current_country}`);
    if (freshState.current_city) stateLines.push(`Current city: ${freshState.current_city}`);
    if (freshState.interested_vacancy) stateLines.push(`Interested vacancy: ${freshState.interested_vacancy}`);
    if (freshState.first_name) stateLines.push(`Candidate first name: ${freshState.first_name}`);
    if (freshState.client_folder_link) stateLines.push(`Client folder link: ${freshState.client_folder_link}`);
    if (Array.isArray(freshState.documents_received) && freshState.documents_received.length) {
      stateLines.push(`Documents received: ${freshState.documents_received.join(', ')}`);
    }
    if (stateLines.length) promptParts.push(`[STATE — результаты предыдущих выяснений (свежие из Supabase)]\n${stateLines.join('\n')}`);
  }
  promptParts.push(`[NEW MESSAGE FROM CANDIDATE]\n${text || '[no text — attachment only]'}`);
  if (hasAttachments) {
    promptParts.push(`[ATTACHMENTS]\n${attachments.map(a => `- ${a.type}: ${a.url}`).join('\n')}`);
  }
  prompt_for_agent = promptParts.join('\n\n');
}

return [{
  json: {
    ...buildContext,
    state: freshState,
    prompt_for_agent, 
    resolved_message: text  // gives feedback context to Save User Message Node
  }
}];
